import { useSyncExternalStore } from 'react';
import { invoke } from '@tauri-apps/api/core';
import { isTauri } from './tauri';
import log from './log';

/// Selectable desktop app icons. Keys must match `ICONS` in
/// ui/desktop/src-tauri/src/app_icon.rs; previews come from
/// ui/web/public/app-icons/, both generated by brand/make-alt-icons.py.
export const APP_ICONS = [
  { id: 'classic', label: 'Classic', blurb: 'The original gradient-ring 2' },
  { id: 'sun', label: 'Rising sun', blurb: 'Red rays, cream ground' },
  { id: 'vennlight', label: 'Venn', blurb: 'Three discs on white' },
  { id: 'graffiti', label: 'Graffiti', blurb: 'Wildstyle X' },
  { id: 'groovebox', label: 'Groovebox', blurb: 'Line-art cube on the grid' },
];

export const DEFAULT_APP_ICON = 'classic';
const STORAGE_KEY = 'inbox2.appIcon';

export function getAppIcon() {
  const stored = localStorage.getItem(STORAGE_KEY);
  return APP_ICONS.some((i) => i.id === stored) ? stored : DEFAULT_APP_ICON;
}

// Subscribers to the current choice — the Settings picker re-renders when a
// theme switch (see `appIcon` in lib/themes.js) changes the icon under it.
const listeners = new Set();
export function useAppIcon() {
  return useSyncExternalStore(
    (cb) => { listeners.add(cb); return () => listeners.delete(cb); },
    getAppIcon,
  );
}

export function previewSrc(id) {
  return `/app-icons/${id}.png`;
}

/**
 * Persist the choice and repaint the running app.
 *
 * The bundle's own icon can't be rewritten by a running process, so this only
 * affects the Dock/taskbar until quit — `applyStoredAppIcon` puts it back on the
 * next launch.
 */
export async function setAppIcon(id) {
  if (!APP_ICONS.some((i) => i.id === id)) return;
  localStorage.setItem(STORAGE_KEY, id);
  listeners.forEach((cb) => cb());
  if (!isTauri()) return;
  try {
    await invoke('set_app_icon', { name: id });
  } catch (err) {
    log.warn('AppIcon', `could not apply icon ${id}: ${err}`);
  }
}

/** Re-apply the stored choice at startup. No-op in the browser. */
export async function applyStoredAppIcon() {
  if (!isTauri()) return;
  const id = getAppIcon();
  if (id === DEFAULT_APP_ICON) return; // already what the bundle ships
  try {
    await invoke('set_app_icon', { name: id });
  } catch (err) {
    log.warn('AppIcon', `could not restore icon ${id}: ${err}`);
  }
}
